<template><div class="metric-tabs"><button v-for="key in keys" :key="key" type="button" :aria-pressed="modelValue === key" @click="$emit('update:modelValue', key)">{{ t(`dashboard.${key}`) }}</button></div></template><script setup lang="ts">import { useI18n } from "vue-i18n"; defineProps<{ modelValue: string; keys: readonly string[] }>(); defineEmits<{ "update:modelValue": [value: string] }>(); const { t } = useI18n();</script><style scoped>.metric-tabs{display:flex;flex-wrap:wrap;gap:6px;border-bottom:1px solid var(--border-color)}button{border:0;background:transparent;color:var(--text-color-secondary);padding:8px;cursor:pointer}button[aria-pressed=true]{color:var(--primary-color);border-bottom:2px solid var(--primary-color)}</style>